import{_ as a,o as t,c as s,a2 as c}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Caching","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/caching.md","filePath":"advanced/caching.md","lastUpdated":1784864016000}'),i={name:"advanced/caching.md"};function n(o,e,h,r,d,l){return t(),s("div",null,[...e[0]||(e[0]=[c(`<h1 id="caching" tabindex="-1">Caching <a class="header-anchor" href="#caching" aria-label="Permalink to &quot;Caching&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>swag2mcp caches downloaded spec files so the MCP server starts faster on subsequent runs. Instead of downloading the same spec file every time, it reuses the cached copy.</p><h2 id="how-caching-works" tabindex="-1">How caching works <a class="header-anchor" href="#how-caching-works" aria-label="Permalink to &quot;How caching works&quot;">​</a></h2><p>When you add a spec with a remote URL, swag2mcp downloads it and saves it to the <code>cache/</code> directory. On the next startup, it checks if the cached copy is still fresh. If it is, the download is skipped.</p><h3 id="what-gets-cached" tabindex="-1">What gets cached <a class="header-anchor" href="#what-gets-cached" aria-label="Permalink to &quot;What gets cached&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Source</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Remote URL</strong> (http/https)</td><td>Always cached. Downloaded once, reused until the cache expires.</td></tr><tr><td><strong>Local file in <code>specs/</code></strong></td><td>Used directly from the <code>specs/</code> directory. Never cached — changes are immediately visible.</td></tr><tr><td><strong>Local file outside <code>specs/</code></strong></td><td>Copied to the cache. If the source file changes (modification time), the cache is invalidated.</td></tr></tbody></table><h3 id="cache-expiration-ttl" tabindex="-1">Cache expiration (TTL) <a class="header-anchor" href="#cache-expiration-ttl" aria-label="Permalink to &quot;Cache expiration (TTL)&quot;">​</a></h3><p>Each cached file gets a random expiration time between <strong>1 hour and 48 hours</strong>. The randomness prevents all cached files from expiring at the same time (which would cause a thundering herd of downloads).</p><ul><li>The TTL is reset every time the MCP server starts</li><li>If a cached file is still within its TTL, it is reused</li><li>If the TTL has expired, the file is downloaded again</li></ul><h3 id="cache-structure" tabindex="-1">Cache structure <a class="header-anchor" href="#cache-structure" aria-label="Permalink to &quot;Cache structure&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.swag2mcp/cache/</span></span>
<span class="line"><span>├── a1b2c3d4e5f6a7b8.spec    # Cached spec file</span></span>
<span class="line"><span>├── a1b2c3d4e5f6a7b8.meta    # Metadata (source, TTL, cached at)</span></span>
<span class="line"><span>├── b2c3d4e5f6a7b8c9.spec</span></span>
<span class="line"><span>├── b2c3d4e5f6a7b8c9.meta</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><p>The cache key is derived from the spec file URL or path. Each cached file has a companion <code>.meta</code> file that stores when it was cached and when it expires.</p><h2 id="managing-the-cache" tabindex="-1">Managing the cache <a class="header-anchor" href="#managing-the-cache" aria-label="Permalink to &quot;Managing the cache&quot;">​</a></h2><h3 id="force-a-refresh" tabindex="-1">Force a refresh <a class="header-anchor" href="#force-a-refresh" aria-label="Permalink to &quot;Force a refresh&quot;">​</a></h3><p>Run <code>swag2mcp update</code> to clear the entire cache and re-download all spec files:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p>This validates the config, clears the cache, and downloads everything fresh.</p><h3 id="clear-the-cache-manually" tabindex="-1">Clear the cache manually <a class="header-anchor" href="#clear-the-cache-manually" aria-label="Permalink to &quot;Clear the cache manually&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span></span></code></pre></div><p>This removes all cached spec files and saved API responses. The next time you start the MCP server, all specs will be downloaded again.</p><h3 id="automatic-cleanup" tabindex="-1">Automatic cleanup <a class="header-anchor" href="#automatic-cleanup" aria-label="Permalink to &quot;Automatic cleanup&quot;">​</a></h3><p>When the MCP server starts (<code>swag2mcp mcp</code>), saved API responses older than 48 hours are automatically removed. This prevents the <code>responses/</code> directory from growing indefinitely.</p><h2 id="important-notes" tabindex="-1">Important notes <a class="header-anchor" href="#important-notes" aria-label="Permalink to &quot;Important notes&quot;">​</a></h2><ul><li><strong>Local files in <code>specs/</code> are never cached</strong> — if you edit a spec file directly in the <code>specs/</code> directory, the changes are immediately visible without clearing the cache</li><li><strong>Remote URLs are always cached</strong> — there is no way to bypass the cache for remote URLs except by running <code>swag2mcp update</code> or <code>swag2mcp clean</code></li><li><strong>The cache is local</strong> — it is stored on disk and does not sync between machines. Use <code>swag2mcp export</code> and <code>swag2mcp import</code> to transfer specs between machines</li></ul>`,25)])])}const g=a(i,[["render",n]]);export{u as __pageData,g as default};
